519	+  /** Voices this review was expected to run. */
520	+  planned: number;
521	+  /** Voices whose result completed (a response and no error). */
522	+  completed: number;
523	+  /** The aggregate verdict-quality band (null when no voice carried an envelope). */
524	+  band: "APPROVED" | "DEGRADED" | "FAILED" | null;
525	+  /** Planned voices without a completed result, as `provider/model`. */
