531	+type OutcomeInput = Pick<MultiModelReviewResult, "modelResults" | "voicesPlanned">;
532	+
533	+/** The outcome of one item's multi-model review. */
534	+export function summarizeVoices(result: OutcomeInput): VoiceOutcome {
535	+  const completedLabels = result.modelResults
536	+    .filter((r) => r.response !== undefined && r.error === undefined)
537	+    .map((r) => `${r.provider}/${r.model}`);
538	+  // (an older pipeline result without voicesPlanned: every attempted voice was planned)
539	+  const plannedLabels = result.voicesPlanned ?? result.modelResults.map((r) => `${r.provider}/${r.model}`);
540	+  const remaining = [...completedLabels];
541	+  const incomplete: string[] = [];
542	+  for (const label of plannedLabels) {
543	+    const i = remaining.indexOf(label);
544	+    if (i >= 0) remaining.splice(i, 1);
545	+    else incomplete.push(label);
546	+  }
547	+  const band = computeVerdictBand(result.modelResults.map((r) => ({ verdictQuality: r.response?.verdictQuality })));
