549	+  const planned = plannedLabels.length;
550	+  return {
551	+    planned,
552	+    completed,
553	+    band,
554	+    incomplete,
555	+    degraded: completed < planned || band === "DEGRADED" || band === "FAILED",
556	+  };
557	+}
